package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {







    @Test
    public void testCreateNumber_HexInteger() {
        Number expected = NumberUtils.createInteger("0x123");
        assertEquals(expected, NumberUtils.createNumber("0x123"));

        Number expectedNeg = NumberUtils.createInteger("-0x123");
        assertEquals(expectedNeg, NumberUtils.createNumber("-0x123"));

        Number expectedUpper = NumberUtils.createInteger("0X123");
        assertEquals(expectedUpper, NumberUtils.createNumber("0X123"));

        Number expectedUpperNeg = NumberUtils.createInteger("-0X123");
        assertEquals(expectedUpperNeg, NumberUtils.createNumber("-0X123"));
    }




















}

