public class NumberUtils_createNumber_TriageGen1Test {













    @Test
    public void testCreateNumber_FloatDoubleBigDecimal() {
        assertEquals(NumberUtils.createFloat("1.23"), NumberUtils.createNumber("1.23"));
        assertEquals(NumberUtils.createDouble("1.23e2"), NumberUtils.createNumber("1.23e2"));
        assertEquals(NumberUtils.createBigDecimal("1.234567890123456789"), NumberUtils.createNumber("1.234567890123456789"));

        // Scientific notation without decimal
