package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {















    @Test
    public void testCreateNumber_SuffixL() {
        assertEquals(NumberUtils.createLong("123L"), NumberUtils.createNumber("123L"));
        assertEquals(NumberUtils.createLong("-123L"), NumberUtils.createNumber("-123L"));
        // BigInteger via L suffix
        String bigStr = "999999999999999999999999999999L";
        assertEquals(NumberUtils.createBigInteger(bigStr), NumberUtils.createNumber(bigStr));

        // Invalid L suffix (has decimal)
        try {
            NumberUtils.createNumber("1.23L");
            fail("Should throw NumberFormatException");
        } catch (NumberFormatException e) {}
    }












}

