package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {

























    @Test
    public void testCreateNumber_AllZerosLogic() {
        // Tests the logic: if (f.floatValue() == 0.0F && !allZeros)
        // "0.0e0" -> mant="0", exp="0", allZeros=true
        assertEquals(NumberUtils.createFloat("0.0e0"), NumberUtils.createNumber("0.0e0"));

        // "0.0000000000000000000000001e0" -> allZeros=false (mant is not all zeros)
        // This should bypass the float return and go to Double/BigDecimal
        Number res = NumberUtils.createNumber("0.0000000000000000000000001e0");
        assertTrue(res instanceof BigDecimal);
    }


}

